CREATE TABLE silver.session_minute_state (`minute_bucket` DateTime('UTC') CODEC(ZSTD(1)), `content_id` Int64 CODEC(ZSTD(1)), `video_session_id` FixedString(64) CODEC(ZSTD(1)), `user_id` FixedString(64) CODEC(ZSTD(1)), `platform` LowCardinality(String) CODEC(ZSTD(1)), `country` LowCardinality(String) CODEC(ZSTD(1)), `app_version` LowCardinality(String) CODEC(ZSTD(1)), `player_version` LowCardinality(String) CODEC(ZSTD(1)), `video_resolution` LowCardinality(String) CODEC(ZSTD(1)), `audio_languages` AggregateFunction(groupUniqArray, String) CODEC(ZSTD(1)), `subtitle_languages` AggregateFunction(groupUniqArray, String) CODEC(ZSTD(1)), `session_start_epoch` AggregateFunction(any, DateTime64(3, 'UTC')) CODEC(ZSTD(1)), `title` AggregateFunction(any, String) CODEC(ZSTD(1)), `video_type` AggregateFunction(any, String) CODEC(ZSTD(1)), `category` AggregateFunction(any, String) CODEC(ZSTD(1)), `show_name` AggregateFunction(any, String) CODEC(ZSTD(1)), `latest_event_type` AggregateFunction(argMax, String, DateTime64(3, 'UTC')) CODEC(ZSTD(1)), `latest_event` AggregateFunction(argMax, String, DateTime64(3, 'UTC')) CODEC(ZSTD(1)), `last_event_ts` SimpleAggregateFunction(max, DateTime64(3, 'UTC')) CODEC(DoubleDelta, ZSTD(1)), `is_active` AggregateFunction(argMax, UInt8, DateTime64(3, 'UTC')) CODEC(ZSTD(1))) ENGINE = SharedAggregatingMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(minute_bucket) ORDER BY (minute_bucket, platform, country, content_id, video_session_id, user_id) SETTINGS index_granularity = 8192